import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const f=JSON.parse('{"title":"User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/index.md","filePath":"user-guide/index.md","lastUpdated":1784984795000}'),n={name:"user-guide/index.md"};function s(o,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="user-manual" tabindex="-1">User Manual <a class="header-anchor" href="#user-manual" aria-label="Permalink to &quot;User Manual&quot;">​</a></h1><p>SwiftList is a fast, keyboard-first file search launcher for Windows. It indexes your local NTFS drives (via the USN Journal and MFT) and network shares in the background, then lets you jump to any file, folder, or application in a fraction of a second.</p><p>This manual covers everything a day-to-day user needs:</p><ul><li><strong><a href="./getting-started.html">Getting Started</a></strong> — installing SwiftList and understanding its three search windows (main, quick, inline).</li><li><strong><a href="./search-syntax.html">Search Syntax</a></strong> — fuzzy matching, exclude/exact/prefix/suffix operators, OR groups, drive targeting, path mode, and pinyin aliasing for Chinese filenames.</li><li><strong><a href="./hotkeys.html">Hotkeys</a></strong> — every configurable shortcut and hardcoded key, with default bindings.</li><li><strong><a href="./actions-and-preview.html">Actions Menu &amp; Preview</a></strong> — the right-click-style actions list and the QuickLook preview pane.</li><li><strong><a href="./instant-answers.html">Instant Answers &amp; Keyword Shortcuts</a></strong> — the calculator, environment variables, run-command shortcuts, and keyword-triggered plugins like Process Manager, Window Switcher, Translation, Browser Data, Settings Search, and Web Search.</li><li><strong><a href="./cli.html">Command-Line Search (slf)</a></strong> — the fzf-style CLI companion for searching from a terminal.</li><li><strong><a href="./uri-protocol.html">URI Protocol (swiftlist://)</a></strong> — jumping straight into a search or a specific setting from a link, another app, or a script.</li><li><strong><a href="./file-manager-support.html">Supported File Managers</a></strong> — which file managers and file-picker dialogs SwiftList can dock into, trigger Quick Navigation from, or detect the current folder of.</li><li><strong><a href="./settings/">Settings Reference</a></strong> — every settings page, tab, and option, itemized.</li><li><strong><a href="./troubleshooting.html">Troubleshooting</a></strong> — common problems and how to fix them.</li><li><strong><a href="./donate.html">Donate</a></strong> — if SwiftList has been useful to you.</li></ul><p>If you&#39;re setting SwiftList up for the first time, start with <strong>Getting Started</strong>.</p>',5)])])}const u=t(n,[["render",s]]);export{f as __pageData,u as default};
